/* Overrides Chirpy's registration script while offline caching is off.
   Liquid prints a boolean false as the string "false", and the theme
   treats every non-empty register query as "register /sw.min.js".
   That string is truthy, so the stock script never unregisters and
   never deletes Cache Storage. Only register=true may register. */
(function () {
  if (!('serviceWorker' in navigator)) return;

  var register = '';
  try {
    var src = document.currentScript && document.currentScript.src;
    if (src) register = new URL(src).searchParams.get('register') || '';
  } catch (err) {
    register = '';
  }

  if (register === 'true') return;

  var clearCaches = function () {
    if (typeof caches === 'undefined') return Promise.resolve();
    return caches.keys().then(function (keys) {
      return Promise.all(
        keys.map(function (key) {
          return caches.delete(key);
        })
      );
    });
  };

  navigator.serviceWorker
    .getRegistrations()
    .then(function (regs) {
      return Promise.all(
        regs.map(function (reg) {
          return reg.unregister();
        })
      );
    })
    .then(clearCaches)
    .catch(function () {});
})();
